public sealed class Account
{
    public decimal Balance { get; private set; }
    public void Apply(object e)
    {
        switch (e)
        {
            case MoneyDeposited d: Balance += d.Amount; break;
            case MoneyWithdrawn w: Balance -= w.Amount; break;
        }
    }
    public static Account Rehydrate(IEnumerable<object> events)
    { var a = new Account(); foreach (var e in events) a.Apply(e); return a; }
}

